<?php
declare(strict_types=1);require_once __DIR__.'/_helper.php';
$sesiId=(int)($_GET['sesi_id']??$_POST['sesi_id']??0);$s=sholat_session($pdo,$sesiId);if(!$s){http_response_code(404);exit('Sesi sholat tidak ditemukan.');}
$cari=trim((string)($_GET['cari']??''));$kelasId=(int)($_GET['kelas_id']??0);$filter=(string)($_GET['status']??'semua');if(!in_array($filter,['semua','belum','SUDAH','BERHALANGAN'],true))$filter='semua';
$kelas=$pdo->query("SELECT id,nama,tingkat,urutan FROM master_kelas WHERE aktif=1 ORDER BY tingkat,urutan,nama")->fetchAll();
$perPage=(int)($_GET['per_page']??20);if(!in_array($perPage,[10,20,50,100],true))$perPage=20;$page=max(1,(int)($_GET['page']??1));
$where=["s.status='aktif'"];$params=[];if($cari!==''){$where[]='(s.nis LIKE ? OR s.nisn LIKE ? OR s.nama LIKE ? OR s.kode_qr LIKE ?)';$q="%$cari%";array_push($params,$q,$q,$q,$q);}if($kelasId>0){$where[]='mk.id=?';$params[]=$kelasId;}
if($filter==='belum')$where[]="ash.id IS NULL";elseif($filter!=='semua'){$where[]='ash.status=?';$params[]=$filter;}$whereSql='WHERE '.implode(' AND ',$where);
$count=$pdo->prepare("SELECT COUNT(*) FROM siswa s LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 JOIN tahun_pelajaran tp2 ON tp2.id=sk2.tahun_pelajaran_id WHERE sk2.siswa_id=s.id AND sk2.status='aktif' AND tp2.aktif=1 ORDER BY sk2.id DESC LIMIT 1) LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id LEFT JOIN absensi_sholat ash ON ash.sesi_id=? AND ash.siswa_id=s.id $whereSql");$count->execute(array_merge([$sesiId],$params));$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));if($page>$pages)$page=$pages;$offset=($page-1)*$perPage;
$st=$pdo->prepare("SELECT s.id,s.nis,s.nisn,s.nama,s.jk,mk.nama nama_kelas,sk.nomor_urut,ash.id absensi_id,ash.status absensi_status,ash.waktu_scan,ash.metode,ash.keterangan FROM siswa s LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 JOIN tahun_pelajaran tp2 ON tp2.id=sk2.tahun_pelajaran_id WHERE sk2.siswa_id=s.id AND sk2.status='aktif' AND tp2.aktif=1 ORDER BY sk2.id DESC LIMIT 1) LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id LEFT JOIN absensi_sholat ash ON ash.sesi_id=? AND ash.siswa_id=s.id $whereSql ORDER BY COALESCE(mk.urutan,9999),COALESCE(sk.nomor_urut,9999),s.nama LIMIT $perPage OFFSET $offset");$st->execute(array_merge([$sesiId],$params));$rows=$st->fetchAll();
$sum=$pdo->prepare("SELECT COUNT(*) total,SUM(ash.status='SUDAH') sudah,SUM(ash.status='BERHALANGAN') berhalangan,SUM(ash.id IS NULL) belum FROM siswa s LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 JOIN tahun_pelajaran tp2 ON tp2.id=sk2.tahun_pelajaran_id WHERE sk2.siswa_id=s.id AND sk2.status='aktif' AND tp2.aktif=1 ORDER BY sk2.id DESC LIMIT 1) LEFT JOIN absensi_sholat ash ON ash.sesi_id=? AND ash.siswa_id=s.id WHERE s.status='aktif'");$sum->execute([$sesiId]);$summary=$sum->fetch()?:[];
$page_title='Daftar Absensi Sholat';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?>
<main class="main"><header class="topbar"><div class="topbar-title">Daftar Absensi Sholat</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content sholat-submodule"><div class="page-header"><div><h1><?=e($s['sholat_nama'])?> — <?=e($s['tanggal'])?></h1><p><?=e($s['nama_sesi'])?> · <?=e($s['tahun_nama'])?> · <?=e($s['semester_nama'])?></p></div><div class="page-header-actions"><a class="btn btn-secondary" href="<?=BASE_URL?>sholat/detail.php?id=<?=$sesiId?>">Kembali</a><?php if($s['status']==='aktif'):?><a class="btn btn-primary" href="<?=BASE_URL?>scanner/index.php?sesi_id=<?=$sesiId?>"><i class="bi bi-qr-code-scan"></i> Scanner</a><?php endif;?></div></div>
<?php if(isset($_GET['saved'])):?><div class="alert alert-success"><?=e((string)$_GET['saved'])?></div><?php endif;?><?php if(isset($_GET['error'])):?><div class="alert alert-danger"><?=e((string)$_GET['error'])?></div><?php endif;?>
<div class="dashboard-grid"><div class="dashboard-card"><div class="card-label">Siswa Aktif</div><div class="card-number"><?= (int)($summary['total']??0)?></div></div><div class="dashboard-card"><div class="card-label">Sudah</div><div class="card-number"><?= (int)($summary['sudah']??0)?></div></div><div class="dashboard-card"><div class="card-label">Belum</div><div class="card-number"><?= (int)($summary['belum']??0)?></div></div><div class="dashboard-card"><div class="card-label">Berhalangan</div><div class="card-number"><?= (int)($summary['berhalangan']??0)?></div></div></div>
<div class="dashboard-table-card"><div class="section-title"><div><h2>Daftar Siswa</h2><p>Status sholat: <strong>Sudah</strong>, <strong>Belum</strong>, atau <strong>Berhalangan</strong>.</p></div></div><form method="get" class="filter-bar"><input type="hidden" name="sesi_id" value="<?=$sesiId?>"><input type="search" class="form-control" name="cari" value="<?=e($cari)?>" placeholder="Cari NIS, NISN, nama, atau QR..."><select class="form-control" name="kelas_id"><option value="0">Semua kelas</option><?php foreach($kelas as $k):?><option value="<?=$k['id']?>" <?=$kelasId===(int)$k['id']?'selected':''?>><?=e($k['nama'])?></option><?php endforeach;?></select><select class="form-control" name="status"><option value="semua">Semua status</option><option value="belum" <?=$filter==='belum'?'selected':''?>>Belum</option><option value="SUDAH" <?=$filter==='SUDAH'?'selected':''?>>Sudah</option><option value="BERHALANGAN" <?=$filter==='BERHALANGAN'?'selected':''?>>Berhalangan</option></select><select class="form-control" name="per_page"><option value="10" <?=$perPage===10?'selected':''?>>10</option><option value="20" <?=$perPage===20?'selected':''?>>20</option><option value="50" <?=$perPage===50?'selected':''?>>50</option><option value="100" <?=$perPage===100?'selected':''?>>100</option></select><button class="btn btn-secondary">Terapkan</button></form>
<div class="table-responsive"><table class="data-table"><thead><tr><th>No.</th><th>Nama</th><th>Kelas</th><th>Status</th><th>Waktu</th><th>Metode</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):$stt=$r['absensi_status']??'BELUM';?><tr><td><?= $r['nomor_urut']!==null?(int)$r['nomor_urut']:'-'?></td><td><strong><?=e($r['nama'])?></strong><br><small><?=e($r['nis'])?></small></td><td><?=e($r['nama_kelas']??'Belum ditempatkan')?></td><td><span class="status-badge status-<?= $stt==='SUDAH'?'aktif':($stt==='BERHALANGAN'?'nonaktif':'draft')?>"><?=e($stt==='SUDAH'?'Sudah':($stt==='BERHALANGAN'?'Berhalangan':'Belum'))?></span></td><td><?=e($r['waktu_scan']??'-')?></td><td><?=e($r['metode']??'-')?></td><td><?php if($s['status']!=='ditutup' && sholat_can_manual()):?><a class="btn btn-secondary btn-sm btn-icon-sm" title="Atur status sholat" aria-label="Atur status sholat" href="<?=BASE_URL?>sholat/manual.php?sesi_id=<?=$sesiId?>&siswa_id=<?=(int)$r['id']?>"><i class="bi bi-pencil-square" aria-hidden="true"></i></a><?php endif;?><?php if(!empty($r['absensi_id']) && user_role()==='admin' && $s['status']!=='ditutup'):?><form method="post" action="<?=BASE_URL?>sholat/hapus_record.php" style="display:inline" onsubmit="return confirm('Hapus record absensi sholat siswa ini? Sesi tetap dipertahankan.')"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$r['absensi_id']?>"><input type="hidden" name="sesi_id" value="<?=$sesiId?>"><button class="btn btn-danger btn-sm btn-icon-sm" type="submit" title="Hapus record" aria-label="Hapus record"><i class="bi bi-trash3" aria-hidden="true"></i></button></form><?php endif;?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="empty-state">Tidak ada data.</td></tr><?php endif;?></tbody></table></div></div>
<div class="pagination-bar"><div class="text-muted">Menampilkan <?=$total?($offset+1).'–'.min($offset+$perPage,$total):'0'?> dari <?=$total?> siswa</div><div class="pagination"><?php for($pg=1;$pg<=$pages;$pg++):?><a class="btn btn-sm <?=$pg===$page?'btn-primary':'btn-secondary'?>" href="?sesi_id=<?=$sesiId?>&cari=<?=rawurlencode($cari)?>&kelas_id=<?=$kelasId?>&status=<?=rawurlencode($filter)?>&per_page=<?=$perPage?>&page=<?=$pg?>"><?=$pg?></a><?php endfor;?></div></div>
</section></main><?php require_once __DIR__.'/../layouts/footer.php';?>
